def ensure_aliases():
    d=ROOT/'assets/images'
    for dst,src in ALIASES.items():
        sp=d/src
        if not sp.exists():
            for suf in ['-1200','-800','-480']:
                cand=d/(src.replace('.webp',f'{suf}.webp'))
                if cand.exists(): sp=cand; break
        if sp.exists() and not (d/dst).exists(): shutil.copy2(sp,d/dst)

def asset(num):
    d=ROOT/'assets/images'; stem=f'adaptprint-source-{num:02d}'
    for suf in ['','-1200','-800','-480']:
        p=d/f'{stem}{suf}.webp'
        if p.exists(): return AS+p.name
    return AS+f'{stem}.webp'

