def nav(cur):
    links=[]
    for u,l in NAV:
        active='active' if u==cur else ''
        current='aria-current="page" ' if u==cur else ''
        links.append(f'<a class="nav-link {active}" {current}href="{u}">{l}</a>')
    return ''.join(links)

